  {
    validate(rec) {
      if (!rec || typeof rec !== "object") return false;
      if (typeof rec.targetIdentity !== "string" || !rec.targetIdentity.trim()) return false;
      if (typeof rec.trigger !== "string" || !rec.trigger.trim()) return false;
