      if (typeof rec.revealed !== "boolean") return false;
      if (typeof rec.hookKey !== "string") return false;
      if (!Number.isFinite(rec.depth)) return false;
      rec.depth = Math.max(1, rec.depth | 0);
      return true;
    },
  }
);

